INSERT INTO public.analytics_documents (id, title, subtitle, doc_type, published_at, language, tags, source_name, source_uri, source_sha256, source_bytes, page_count, markdown, content_hash, extraction, metadata, collected_at, created_at, updated_at) VALUES ('alfa-policy-rate-2026-09-11', 'Ключевая ставка ЦБ РФ', 'Ставка без изменения на 14,0%, риторика стала жестче', 'rates', '2026-09-11 00:00:00+00', 'ru', '{"ключевая ставка","ЦБ РФ",инфляция,"денежно-кредитная политика"}', 'ALFA-Macro_Insights-Policy_Rate_11Sep.pdf', 'ALFA-Macro_Insights-Policy_Rate_11Sep.pdf', NULL, NULL, NULL, 'ЦБ РФ принял решение оставить ставку неизменной на уровне 14,0%: ЦБ РФ на сегодняшнем заседании принял решение взять паузу и оставить ставку неизменной на уровне 14,0%. Формально сигнал пресс-релиза осталсЯ нейтральным: ЦБ РФ кбудет принимать дальнейшие решения ПО ключевой ставке в заВисИмости динамики инфляции и инфляционных ожиданий; также оценки рисков co стороны внутренних и внешних УСЛОВИЙ&gt; . Однако на пресс-конференции глава ЦБ РФ пояснила; ЧТО совет директоров предметно обсуждал ТОЛЬКО вариант паузы; а вариант снижения не рассматривался; кроме ТОГО , пресс-релиз   содержит несколько важных корректировок в коммуникации также свидетельствующих об ужесточении ПОЗИЦИИ:

ЦБ РФ отметил ускорение роста цен в устойчивых компонентах до 5 6%: Сам факт, что в начале прессрелиза отмечается ускорение инфляции устойчивых компонентах , говорит об ужесточении тональности комментария ЦБ РФ: Напомним; что до этого показатели устойчивой инфляции в течение длительного времени держались на значениях 4-5%. Смещение вверх диапазона оценок устойчивой инфляции подтверждается другими метриками ЦБ РФ: например, индекс базовой инфляции без туризма с июня по июль вырос с 5,7% ДО 7,6% соответственно (это соответствовало ускорению показателя усредненной за 3 месяца базовой инфляции с 4,1% 5,4%). Это свидетельствует ЧТО временный ценовой ШОК последних месяцев на стороне предложения транслируется на устойчивые   компоненты; ЧТО ДОЛЖНО быть отражено при прочих равных большей жесткости решений ДКП.

Проинфляционные риски связаны Фболее продолжительным выбытиемэ производственных мощностей: Следует отметить ЧТО впервые c начала текущего года в релизе отмечено ЧТО проинфляционные рИСКИ выросли до ЭТОГО использовалась формулировка, ЧТО проинфляционные риски преобладают над дезинфляционными: По оценке ЦБ РФ; основные проинфляционные риски ксвязаны € дисбалансом спроса предложения случае более ВЫСОКОГО внутреннего спроса и более продолжительного выбытия производственных мощностей в отдельных отраслях . Напомним; ЧТо в предыдущем пресс-релизе речь шла квременном выбытии производственных мощностей отдельных отрасляхэ Эта часть пресс-релиза также подтверждает, ЧТО концепция краткосрочности ограничений co стороны предложения В будущем может быть переосмыслена

Высокий уровень инфляционных ожиданий остается под вниманием руководства ЦБ РФ: Глава ЦБ РФ в выступлении уделила большое внимание повышенному уровню инфляционных ожиданий; которые остаются ИСТОЧНИКОМ риска Обновленных данных по инфляционным ожиданиям населения за сентябрь пока нет, HO августе показатель составил 13,7%, что было выше среднего значения 13,2% за 2025 ГОд 13,3% за 7M26. Кроме того, консенсус-прогноз аналитиков В сентябре показал увеличение инфляционных ожиданий прогноз среднего значения инфляции на 2026 г. в сентябре вырос минимально с 6,0% до 6,1%, но прогноз инфляции на 2027 увеличился более заметно с 4,9% до 5,2%. Также выросли и инфляционные ожидания предприятий показатель  ожидаемой на ближайшие три месяца инфляции сентябре составил 7,0%, Что сопосТавимо уровнями начала 2025 года. Косвенно повышенные инфляционные ожидания транслируют и финансовые рынки доходности рынка ОФЗ в последние месяцы оставались на высоком уровне несмотря на паузу в размещении новых выпусков ОФЗ, которую брал Минфин:

Динамика корпоративных кредитов и бюджетный   фактор главные индикаторы состояния спроса на ближайшее время: Hа пресс-конференции глава ЦБ РФ подчеркнула; ЧТО в ближайшее время денежные власти будут пристально мониторить состояние спроса через два индикатора: Первый это динамика корпоративного кредитования; которое сейчас; напомним; идет по траектории более быстрого роста по сравнению c прогнозами ЦБ РФ (см нашу публикацию кПрогноз решения ПО ставке 11 сентября: Ждем паузу на 14,0% В сентябре; неопределенность смещается на 4К2бж от 4 сентября 2026 г.): Вторым фактором остаются вводные по бюджету в конце этого месяца Минфин должен представить параметры нового трехлетнего бюджета: Хотя в августе федеральный бюджет сведен c профицитом 0,7 трлн руб: накопленный дефицит бюджета остается 5,8 трлн руб: что существенно выше прогнозов:

Мы ожидаем сохранения паузы на заседании 23 октября: С учетом риторики ЦБ РФ мы меняем наш взгляд на динамику ключевой ставки на этот гоД: Если раньше мы ориентировались на ставку на уровне 13,5% на конец 2026 г то теперь мы ожидаем ee сохранения на текущем значении 14,0% до коНца года. При этом наш прогНоз по ставке на конец 2027 г. остается на уровне 12,0%.

