INSERT INTO public.analytics_documents (id, title, subtitle, doc_type, published_at, language, tags, source_name, source_uri, source_sha256, source_bytes, page_count, markdown, content_hash, extraction, metadata, collected_at, created_at, updated_at) VALUES ('alfa-russian-steels-1q21', 'Российская сталь', 'Ралли цен продолжается; прогноз результатов за 1К21', 'equity', '2021-04-15 00:00:00+00', 'ru', '{сталь,металлургия,НЛМК,ММК,Северсталь,акции}', 'ALFA_Russian_Steels_1К21PreviewUpdate_15Apr2021.pdf', 'ALFA_Russian_Steels_1К21PreviewUpdate_15Apr2021.pdf', NULL, NULL, NULL, 'Подводя итоги первого квартала; мы ожидаем; что производители плоского проката представят сильные финансовые результаты на фоне стабильных объемов производства после завершения крупных ремонтов за счет роста цен на сталь Поскольку Европа не может удовлетворить отложенный спрос в связи с медленным перезапуском остановленных мощностей; спрос в США растет после нового пакета стимулов; мы ожидаем; что рентабельность крупнейших российских производителей стали улучшится за счет экспортных продаж и благодаря их эффективной сырьевой интеграции. Отметим, что цены на сырье росли более медленным темпом в сравнении c ценами на сталь в 1К21 Рост оборотного капитала предполагает усиление давления на квартальный СДП: Тем не менее; мы ожидаем; ЧТО дивидендная доходность производителей в среднем составит не менее 2%, c высокой вероятностью доходности выше наших ожиданий Высокие цены на сталь выглядят устойчивыми на горизонте 2-3 месяцев: предложение на гк прокат на заводах турции началу Рамадана приблизилось к $1 ООО/т, внутренние цены на прокат США; судя по всему, не достигли своих максимумов; торгуясь в диапазоне $1 350-1 4ОО/кт: Цены на гlк прокат Северной Европе достигли $1 069-1 128/т первую декаду апреля: Цены на гlк прокат; FOB; Черное море на прошлой неделе были в диапазоне $830-840/т, что указывает на тО , что средние цены на сталь в 2К21 могут превзойти ценовые уровни 1К21

Объемы продаж: Предварительные данные указывают на то; чТо на объемы продаж НЛМК MMК повлияли сезонность и технические факторы: Суровые погодные условия зимой этого года влияли на поставки на Урале и в Сибири; тогда как неблагоприятные погодные условия портах Черного моря привели к созданию узких мест при поставках на экспорт: Эти факторы как и увеличение сроков реализации СвЯЗИ c экспортными поставками; привели росту оборотного капитала: Продажи готовой продукции MMК составили 2,9 млн т (+ 5,8 % гlг): тогда как НЛМК поставил в общей сложности 3,9 млн т, что на 13% ниже гlг из-за снижения продаж полуфабрикатов роста внутригрупповых поставок: Мы ожидаем; ЧТО объемы продаж Северстали будут сопоставимы квартальном сравнении ожидаем   увеличение ДОЛИ экспОрта: Компания представит СвОИ ключевые операционные результаты одновременно финансовыми. Что касается конъюнктуры цен; мы отмечаем; ЧТО, хотя цены на непокрытый прокат в долларовом выражении выросли почти в два раза гlг; рост премии на внутреннем рынке отставал из-за большего спроса на экспортных рынках что повышение цен будет иметь отложенный эффект на выручку в силу природы бизнеса; связанного с поставками и меняющейся долей продаж по спот-ценам.

EBITDA: Так как рОст цен на сталь опережал рОст цен на сырье; мы ожидаем; рентабельности продемонстрирует даже наименее интегрированный сравнении компаниями-аналогами MMК: Сильный спрос на сталь на экспОртных рынках; как мы считаем поможет нейтрализовать укрепление курса рубля на 2% ; произошедшее 1К21 Мы ожидаем ЧТО компании продемонстрируют рекордно ВЫСОКИЙ квартальный показатель EBITDA дальнейшим потенциалом роста 2K21, так как рОст цен на сталь 2К21 продолжился Справедливости  ради следует ЧТО на 4К20 EBITDA НЛМК начисленное возмещение в свЯЗИ с импортом слябов в США (около $100 млн): Без учета ЭТОГО фактора рост EBITDA НЛМК в 1К21 был бы близок к 40% Кк:

СДП и дивиденды: Сильный прирост EBITDA поддерживает ожидания отношении СДП компаний При этом стоит учитывать заявленный уровень инвестиций по Северстали; НЛМК ММК размере около $3,5 млрд в 2021. Инвестиции в первом квартале традиционно ниже и будут нарастать течение года. Отметим   отдельно; ЧТО рост цен на сталь сырье влияет на увеличение стоимости запасов; тогда как логистические аспекты также влияют на увеличение оборотного капитала: Наш прогноз СДП предполагает возможную коррекцию СВЯЗИ динамикой оборотного капитала Отдельно отметим; ЧТО на СДП НЛМК должны повлиять денежные средства от возврата пошлины на импорт слябов в 4К20. Мы полагаем ; ЧТо производители стали направят на дивидендные выплаты 100% СДП на квартальной основе Это предполагает дивиденд на акцию на уровне $0,45/ГДР для $0,59/ГДР для Северстали; $0,69ГДР для НЛМК.

