INSERT INTO public.analytics_documents (id, title, subtitle, doc_type, published_at, language, tags, source_name, source_uri, source_sha256, source_bytes, page_count, markdown, content_hash, extraction, metadata, collected_at, created_at, updated_at) VALUES ('alfa-7m26', 'Макростатистика 7М26', 'Данные по рынку труда не подтверждают охлаждения экономики', 'macro', '2026-09-07 00:00:00+00', 'ru', '{макроэкономика,"рынок труда",потребление,"розничная торговля"}', 'ALFA-7M26.pdf', 'ALFA-7M26.pdf', NULL, NULL, NULL, 'Ключевым вопросом текущих месяцев является скорость охлаждения рынка труда; этот   фактор выглядит основным аргументом в пользу возможного продолжения цикла снижения ставки Доступные оперативные данные и показатели рынка труда летом 2026 г: оставались достаточно сильными: несмотря на замедление темпов роста зарплат; в июне показатель их роста оставался на уровне 9,6% гlг, a рост числа вакансий за лето 2026 ., по данным HeadHunter, составил 12% против их увеличения на 4-5% за аналогичный период предыдущих двух лет: Рост оборота розничной торговли был на уровне 5,3% rlг в июле, что поддерживает наше ожидание, что ключевым вызовом для экономики будут ограничения co стороны предложения, a не торможение спроса:

Оборот розничной торговли в июле вырос на 5,3% rlг, динамика спроса складывалась в рамках ожиданий Динамика спроса в июле складывалась в рамках наших ожиданий; темпы роста оборота розничной торговли замедлились До 5,3%   гlг после периода быстрого роста на 7,2% гэг 2К26. Основной причиной мы считаем замедление роста потребления сегменте непродовольственных товаров; в частности в сегменте покупок автомобилей В июле продажи легковых автомобилей были на уровне пика 124 ШТ: Hо годовом выражении ЭТОТ показатель уже демонстрировал нулевой рост после роста на уровне 19% rlr в 2К26; поскольку в прошлом году спрос начал   быстро восстанавливаться именно середины ближайшие месяцы Мы ожидаем проявления эффекта базы (см Рис.1) В ближайшие месяцы ориентируемся на дополнительное замедление роста потребления на фоне более слабых продаж автомобилей августе объем их продаж упал на 7% Как июлю 2026 Г; так и выражении: При этом замедление роста спроса происходит в условиях значимого торможения динамики предложения (см Рис 2)

