INSERT INTO public.analytics_documents (id, title, subtitle, doc_type, published_at, language, tags, source_name, source_uri, source_sha256, source_bytes, page_count, markdown, content_hash, extraction, metadata, collected_at, created_at, updated_at) VALUES ('alfa-gold-aug-2026', 'Обзор рынка золота: август 2026', 'Золото заметно выросло за август, но жесткий сигнал ФРС охладил ралли', 'commodities', '2026-09-01 00:00:00+00', 'ru', '{золото,"сырьевые товары",ФРС,доллар,Китай}', 'Gold_digest_August26.pdf', 'Gold_digest_August26.pdf', NULL, NULL, NULL, 'Август стал месяцем восстановления для драгметалла: в моменте золото показало лучший месячный результат с января В ходе ралли котировки вернулись в область $4 650-4 700 за унцию С $4 00О за унцию; затем скорректировались примерно $4 400 на конец месяца

Слабый июльский отчет по занятости и более спокойные месячные показатели инфляции уменьшили опасения немедленного повышения ставки ФРС Ослабление доллара США; продолжающиеся покупки драгметалла мировыми ЦБ и возвращение инвесторов в ETF поддержали спрос; Более того, 19 августа Минфин США внепланово объявил об увеличении выкупа собственных гособлигаций сроком 10 30 лет, что существенно подтолкнуло котировки золота вверх. Это фактически признание тоГо, что занимать на 30 лет государству стало слишком дорого, Реакция рынка была незамедлительной: американский доллар ослаб до 98 пунктов по индексу DXY Цены на золото при этом в тот же день выросли: более чем на примерно до $4 520 за унцию Это сильнейший дневной рост за полгода: Отметим , что такое действие Минфина США не смутило рынок , скорее тайминг анонса Минфин США обычно публикует свои планы по строгому графику раз в квартал и редко устраивает инвесторам и рынку сюрпризы Отсюда такая реакция новости появились всего через две недели после анонса квартального плана При этом увеличение объемов байбека С млрд до $4 млрд можно назвать небольшим С рамках общего американского госдолга результате; золото практически в любом случае остается в сильной позиции: если данный ряд последовательных действий Минфина США сработает, то ставки по длинным гособлигациям США снизятся; a металл пойдет вверх, a в случае; если не сработает то программу байбека потенциально могут расширить; и это надавит на инфляцию золото; как следствие, вырастет в цене 4%;

28 августа Кевин Уорш; глава ФРС, подчеркнул устойчивость экономики и приоритет борьбы инфляцией Переоценка перспектив ставки повысила альтернативную стоимость владения золотом; рост доходностей американских облигаций и отскок доллара США затормозили ралли; Более того, на прошлой неделе цена золота резко снизилась после выхода сильных данных по рынку труда США, которые повысили ожидания возможного повышения ставки Федеральной резервной системой августе число рабочих мест вне сельского хозяйства США выросло на 162 тысячи после пересмотра показателей за предыдущие два месяца в сторону повышения Это оказалось выше всех прогнозов аналитиков, Между тем; безработица сохранилась на уровне 4,1%. Сильная статистика заставила трейдеров активнее закладывать в цены повышение ставки ФРС в сентябре; Вероятность такого решения оценивается

примерно в 60%, тогда как ранее участники рынка практически не делали на него ставку После публикации данных укрепился доллар США до 99 пунктов; a доходность двухлетних гособлигаций США выросла до 4,3%, Для золота это негативный фактор; Теперь внимание рынка переключается на данные по потребительской инфляции в США; которые выйдут на этой неделе Именно они могут стать ключевым фактором для решения ФРС по ставке 16-ого сентября

Пекин сейчас активно использует косвенную стратегию "золотого обеспечения юаня для ускорения интернационализации своей валюты , Вместо того, чтобы привязывать курс юаня, что лишило бы Народный Китая независимости в денежно кредитной политике инфраструктура, построенная в таких центрах как Шанхай и Гонконг; действует как механизм укрепления доверия в двусторонней торговле Это позволяет иностранным компаниям осуществлять операции в юанях С четкой гарантией того, что они смогут беспрепятственно конвертировать эти доходы в физическое золото банк

Реальная цель расширения золотых запасов Китая И создания локализованных оффшорных клиринговых экосистем заключается создании параллельного финансового цикла: сырье-юань-золото  Эта структура позволяет ключевым поставщикам сырья таким как; K примеру, Россия, Иран; a также, возможно; странам Персидского залива; продавать нефть или сырье Китаю напрямую за юани; Более того, торговые партнеры которые не решаются хранить фиатные юани из-за строгого контроля за движением капитала в Китае, могут мгновенно купить драгметалл через Шанхайскую биржу золота (SGE) или новую центральную клиринговую систему по драгоценным металлам Гонконга: Благодаря интеграции SGE на материковой части Китая оффшорной инфраструктурой в Гонконге расчеты по транзакциям осуществляются исключительно в юанях, a клиринг осуществляется использованием незападной инфраструктуры. Это делает систему неуязвимой для замораживания активов на Западе или запрета SWIFT

Диверсификация резервов центральных банков; широкий спрос на золотые ETF и покупки в Азии остаются опорой рынка золота. Рост госдолга США и геополитическая неопределенность повышают интерес К золоту как активу без обязательств суверенного эмитента .

