INSERT INTO public.analytics_chunks (id, document_id, ordinal, kind, section_path, text, embedding_text, content_hash, input_hash, chars, size, pages, page_from, page_to, table_refs, metadata, created_at, updated_at) VALUES ('alfa-policy-rate-2026-09-11#6de0941232e56390', 'alfa-policy-rate-2026-09-11', 0, 'text', '{"Ставка без изменения на 14,0%, риторика стала жестче"}', 'ЦБ РФ принял решение оставить ставку неизменной на уровне 14,0%: ЦБ РФ на сегодняшнем заседании принял решение взять паузу и оставить ставку неизменной на уровне 14,0%. Формально сигнал пресс-релиза осталсЯ нейтральным: ЦБ РФ кбудет принимать дальнейшие решения ПО ключевой ставке в заВисИмости динамики инфляции и инфляционных ожиданий; также оценки рисков co стороны внутренних и внешних УСЛОВИЙ&gt; . Однако на пресс-конференции глава ЦБ РФ пояснила; ЧТО совет директоров предметно обсуждал ТОЛЬКО вариант паузы; а вариант снижения не рассматривался; кроме ТОГО , пресс-релиз   содержит несколько важных корректировок в коммуникации также свидетельствующих об ужесточении ПОЗИЦИИ:

ЦБ РФ отметил ускорение роста цен в устойчивых компонентах до 5 6%: Сам факт, что в начале прессрелиза отмечается ускорение инфляции устойчивых компонентах , говорит об ужесточении тональности комментария ЦБ РФ: Напомним; что до этого показатели устойчивой инфляции в течение длительного времени держались на значениях 4-5%. Смещение вверх диапазона оценок устойчивой инфляции подтверждается другими метриками ЦБ РФ: например, индекс базовой инфляции без туризма с июня по июль вырос с 5,7% ДО 7,6% соответственно (это соответствовало ускорению показателя усредненной за 3 месяца базовой инфляции с 4,1% 5,4%). Это свидетельствует ЧТО временный ценовой ШОК последних месяцев на стороне предложения транслируется на устойчивые   компоненты; ЧТО ДОЛЖНО быть отражено при прочих равных большей жесткости решений ДКП.', 'Документ: Ключевая ставка ЦБ РФ
