INSERT INTO public.analytics_chunks (id, document_id, ordinal, kind, section_path, text, embedding_text, content_hash, input_hash, chars, size, pages, page_from, page_to, table_refs, metadata, created_at, updated_at) VALUES ('alfa-macro-1h26#29686ab53d702626', 'alfa-macro-1h26', 4, 'text', '{"Рынок труда в мае-июне дает сигнал о6 охлаждении"}', 'Главной темой июня стала слабая динамика предложения; Несмотря на календарный фактор (2 дополнительных рабочих дня по сравнению С июнем 2025 Г ) рост промпроизводства составил только 0,6% гг; Основной причиной такой слабой динамики было снижение производства нефтепродуктов в июне на 21,7% г/г; спад в этом сегменте нейтрализовал эффект от сильного роста выпуска в машиностроительном сегменте (+17,0% гАг в июне) (см Рис1)

Динамика спроса при этом оставалась сильной Рост оборота розничной торговли составил 7,3% г/г в июне, что близко росту на 7,8% в в непродовольственном сегменте рост потребления в июне составил значительные мае, При этом сфера услуг продемонстрировала более слабую динамику: рост потребления в этом сегменте составил всего 1,7% гАг в июне после 2,3% г|г в мае результате темпы роста ВВП составили только 1,1% г/г в июне; вместо 2,5% г/г за 2К26 ВВП выр только 0,9% гАг (см Рис 2)', 'Документ: Макростатистика 1П26
Раздел: Рынок труда в мае-июне дает сигнал о6 охлаждении

Главной темой июня стала слабая динамика предложения; Несмотря на календарный фактор (2 дополнительных рабочих дня по сравнению С июнем 2025 Г ) рост промпроизводства составил только 0,6% гг; Основной причиной такой слабой динамики было снижение производства нефтепродуктов в июне на 21,7% г/г; спад в этом сегменте нейтрализовал эффект от сильного роста выпуска в машиностроительном сегменте (+17,0% гАг в июне) (см Рис1)

Динамика спроса при этом оставалась сильной Рост оборота розничной торговли составил 7,3% г/г в июне, что близко росту на 7,8% в в непродовольственном сегменте рост потребления в июне составил значительные мае, При этом сфера услуг продемонстрировала более слабую динамику: рост потребления в этом сегменте составил всего 1,7% гАг в июне после 2,3% г|г в мае результате темпы роста ВВП составили только 1,1% г/г в июне; вместо 2,5% г/г за 2К26 ВВП выр только 0,9% гАг (см Рис 2)', '29686ab53d7026264a03e9a3d559bc8ee377b693c66616454e2a7d1ef110b878', '82197b0075264e99858b4dd073fe5048659fd19ccf908f614a8787572c4f62c5', 902, 243, '{2}', 2, 2, '[]', '{"oversized": false, "source_size": 243, "source_chunk_id": "ALFA-macro_stat1H26#0005"}', '2026-10-22 15:55:26.188188+00', '2026-10-22 15:55:26.188188+00') ON CONFLICT DO NOTHING;
INSERT INTO public.analytics_chunks (id, document_id, ordinal, kind, section_path, text, embedding_text, content_hash, input_hash, chars, size, pages, page_from, page_to, table_refs, metadata, created_at, updated_at) VALUES ('alfa-macro-1h26#5efc7ecb471cef22', 'alfa-macro-1h26', 5, 'text', '{"Рынок труда в мае-июне дает сигнал о6 охлаждении"}', 'Важной частью сильной динамики конечного потребления оставался спрос на автомобили; В июне население купило 118 тыс; новых легковых машин что сопоставимо С пиковыми значениями текущего года, наблюдавшимися в апреле (см Рис 3) Недельные данные указывают на сохранение продаж в июле вблизи этих уровней; но С точки зрения годовой динамики, поскольку спрос на автомобили в 2025 Г начал восстанавливаться c 2П25; темпы роста в этом сегменте в ближайшие месяцы уйдут в отрицательную зону учетом сильного всплеска цен на бензин; которые выросли на 7% за июнь и на 26 % за последние 12 месяцев (по состоянию на 27 июля) мы полагаем; что риски охлаждения спроса на автомобили действительно значимы; пользу этого говорят снижение выдач автокредитов и ужесточение макропруденциальных лимитов по ним с 1 октября,

Динамика инвестиций, 0 которой можно судить по строительной отрасли (спад на 5,0% за 1П26), остается отрицательной, и с учетом обозначившихся

Рис1: Динамика выпуска в отраслях промышленности; % г/г

летом рисков для производственных мощностей; мы не исключаем возможности негативного сюрприза', 'Документ: Макростатистика 1П26
Раздел: Рынок труда в мае-июне дает сигнал о6 охлаждении

