INSERT INTO public.analytics_chunks (id, document_id, ordinal, kind, section_path, text, embedding_text, content_hash, input_hash, chars, size, pages, page_from, page_to, table_refs, metadata, created_at, updated_at) VALUES ('alfa-macro-1h26#fd4da18077e50436', 'alfa-macro-1h26', 7, 'text', '{"Рынок труда в мае-июне дает сигнал о6 охлаждении"}', 'Статистика за июнь демонстрирует сохраняющийся разрыв между динамикой потребления, которая оставалась сильной, и слабым предложением; Шок предложения нашел отражение во всплеске цен на топливо в июне порядка трети роста цен за месяц было связано С этим фактором; и его вес остается на уровне 50% в июле; При этом мы видим перенос повышенных цен на топливо В конечные цены В продовольственном сегменте за исключением плодоовощной продукции темпы роста цен постепенно ускоряются, в итоге индикатор базовой инфляции остается повышенным уже 5 недель; что говорит об устойчивости спроса И 0 способности предприятий переносить издержек в динамику конечных цен; Данные по инфляции говорят 0 переориентации спроса С потребления услуг (туристических) на потребление товаров что также может работать в пользу сохранения повышенного инфляционного давления  Напомним, что после инфляции на уровне 0,87 м/м в июне мы ожидаем рост цен 0,7% м/м в июле И 0,2% м/м в августе что выведет показатель годовой рост

