INSERT INTO public.analytics_chunks (id, document_id, ordinal, kind, section_path, text, embedding_text, content_hash, input_hash, chars, size, pages, page_from, page_to, table_refs, metadata, created_at, updated_at) VALUES ('alfa-russian-steels-1q21#c8ad985bebc19c1c', 'alfa-russian-steels-1q21', 3, 'text', '{"Ралли цен продолжается; прогноз результатов за 1К21"}', 'СДП и дивиденды: Сильный прирост EBITDA поддерживает ожидания отношении СДП компаний При этом стоит учитывать заявленный уровень инвестиций по Северстали; НЛМК ММК размере около $3,5 млрд в 2021. Инвестиции в первом квартале традиционно ниже и будут нарастать течение года. Отметим   отдельно; ЧТО рост цен на сталь сырье влияет на увеличение стоимости запасов; тогда как логистические аспекты также влияют на увеличение оборотного капитала: Наш прогноз СДП предполагает возможную коррекцию СВЯЗИ динамикой оборотного капитала Отдельно отметим; ЧТО на СДП НЛМК должны повлиять денежные средства от возврата пошлины на импорт слябов в 4К20. Мы полагаем ; ЧТо производители стали направят на дивидендные выплаты 100% СДП на квартальной основе Это предполагает дивиденд на акцию на уровне $0,45/ГДР для $0,59/ГДР для Северстали; $0,69ГДР для НЛМК.', 'Документ: Российская сталь
Раздел: Ралли цен продолжается; прогноз результатов за 1К21

