INSERT INTO public.analytics_chunks (id, document_id, ordinal, kind, section_path, text, embedding_text, content_hash, input_hash, chars, size, pages, page_from, page_to, table_refs, metadata, created_at, updated_at) VALUES ('alfa-russian-steels-1q21#850a5e5c669e5d7a', 'alfa-russian-steels-1q21', 0, 'text', '{"Ралли цен продолжается; прогноз результатов за 1К21"}', 'Подводя итоги первого квартала; мы ожидаем; что производители плоского проката представят сильные финансовые результаты на фоне стабильных объемов производства после завершения крупных ремонтов за счет роста цен на сталь Поскольку Европа не может удовлетворить отложенный спрос в связи с медленным перезапуском остановленных мощностей; спрос в США растет после нового пакета стимулов; мы ожидаем; что рентабельность крупнейших российских производителей стали улучшится за счет экспортных продаж и благодаря их эффективной сырьевой интеграции. Отметим, что цены на сырье росли более медленным темпом в сравнении c ценами на сталь в 1К21 Рост оборотного капитала предполагает усиление давления на квартальный СДП: Тем не менее; мы ожидаем; ЧТО дивидендная доходность производителей в среднем составит не менее 2%, c высокой вероятностью доходности выше наших ожиданий Высокие цены на сталь выглядят устойчивыми на горизонте 2-3 месяцев: предложение на гк прокат на заводах турции началу Рамадана приблизилось к $1 ООО/т, внутренние цены на прокат США; судя по всему, не достигли своих максимумов; торгуясь в диапазоне $1 350-1 4ОО/кт: Цены на гlк прокат Северной Европе достигли $1 069-1 128/т первую декаду апреля: Цены на гlк прокат; FOB; Черное море на прошлой неделе были в диапазоне $830-840/т, что указывает на тО , что средние цены на сталь в 2К21 могут превзойти ценовые уровни 1К21', 'Документ: Российская сталь
Раздел: Ралли цен продолжается; прогноз результатов за 1К21

Подводя итоги первого квартала; мы ожидаем; что производители плоского проката представят сильные финансовые результаты на фоне стабильных объемов производства после завершения крупных ремонтов за счет роста цен на сталь Поскольку Европа не может удовлетворить отложенный спрос в связи с медленным перезапуском остановленных мощностей; спрос в США растет после нового пакета стимулов; мы ожидаем; что рентабельность крупнейших российских производителей стали улучшится за счет экспортных продаж и благодаря их эффективной сырьевой интеграции. Отметим, что цены на сырье росли более медленным темпом в сравнении c ценами на сталь в 1К21 Рост оборотного капитала предполагает усиление давления на квартальный СДП: Тем не менее; мы ожидаем; ЧТО дивидендная доходность производителей в среднем составит не менее 2%, c высокой вероятностью доходности выше наших ожиданий Высокие цены на сталь выглядят устойчивыми на горизонте 2-3 месяцев: предложение на гк прокат на заводах турции началу Рамадана приблизилось к $1 ООО/т, внутренние цены на прокат США; судя по всему, не достигли своих максимумов; торгуясь в диапазоне $1 350-1 4ОО/кт: Цены на гlк прокат Северной Европе достигли $1 069-1 128/т первую декаду апреля: Цены на гlк прокат; FOB; Черное море на прошлой неделе были в диапазоне $830-840/т, что указывает на тО , что средние цены на сталь в 2К21 могут превзойти ценовые уровни 1К21', '850a5e5c669e5d7a6ccae535846d75906520377a072451271029b0012a9535dc', 'f6e6d146053f928fa88aa4544af95626813aff70c55abe37389dd821bb311ff4', 1388, 366, '{1}', 1, 1, '[]', '{"oversized": false, "source_size": 366, "source_chunk_id": "ALFA_Russian_Steels_1К21PreviewUpdate_15Apr2021#0001"}', '2026-10-22 15:55:26.210565+00', '2026-10-22 15:55:26.210565+00') ON CONFLICT DO NOTHING;
INSERT INTO public.analytics_chunks (id, document_id, ordinal, kind, section_path, text, embedding_text, content_hash, input_hash, chars, size, pages, page_from, page_to, table_refs, metadata, created_at, updated_at) VALUES ('alfa-russian-steels-1q21#a096a55f72539511', 'alfa-russian-steels-1q21', 1, 'text', '{"Ралли цен продолжается; прогноз результатов за 1К21"}', 'Объемы продаж: Предварительные данные указывают на то; чТо на объемы продаж НЛМК MMК повлияли сезонность и технические факторы: Суровые погодные условия зимой этого года влияли на поставки на Урале и в Сибири; тогда как неблагоприятные погодные условия портах Черного моря привели к созданию узких мест при поставках на экспорт: Эти факторы как и увеличение сроков реализации СвЯЗИ c экспортными поставками; привели росту оборотного капитала: Продажи готовой продукции MMК составили 2,9 млн т (+ 5,8 % гlг): тогда как НЛМК поставил в общей сложности 3,9 млн т, что на 13% ниже гlг из-за снижения продаж полуфабрикатов роста внутригрупповых поставок: Мы ожидаем; ЧТО объемы продаж Северстали будут сопоставимы квартальном сравнении ожидаем   увеличение ДОЛИ экспОрта: Компания представит СвОИ ключевые операционные результаты одновременно финансовыми. Что касается конъюнктуры цен; мы отмечаем; ЧТО, хотя цены на непокрытый прокат в долларовом выражении выросли почти в два раза гlг; рост премии на внутреннем рынке отставал из-за большего спроса на экспортных рынках что повышение цен будет иметь отложенный эффект на выручку в силу природы бизнеса; связанного с поставками и меняющейся долей продаж по спот-ценам.', 'Документ: Российская сталь
Раздел: Ралли цен продолжается; прогноз результатов за 1К21

Объемы продаж: Предварительные данные указывают на то; чТо на объемы продаж НЛМК MMК повлияли сезонность и технические факторы: Суровые погодные условия зимой этого года влияли на поставки на Урале и в Сибири; тогда как неблагоприятные погодные условия портах Черного моря привели к созданию узких мест при поставках на экспорт: Эти факторы как и увеличение сроков реализации СвЯЗИ c экспортными поставками; привели росту оборотного капитала: Продажи готовой продукции MMК составили 2,9 млн т (+ 5,8 % гlг): тогда как НЛМК поставил в общей сложности 3,9 млн т, что на 13% ниже гlг из-за снижения продаж полуфабрикатов роста внутригрупповых поставок: Мы ожидаем; ЧТО объемы продаж Северстали будут сопоставимы квартальном сравнении ожидаем   увеличение ДОЛИ экспОрта: Компания представит СвОИ ключевые операционные результаты одновременно финансовыми. Что касается конъюнктуры цен; мы отмечаем; ЧТО, хотя цены на непокрытый прокат в долларовом выражении выросли почти в два раза гlг; рост премии на внутреннем рынке отставал из-за большего спроса на экспортных рынках что повышение цен будет иметь отложенный эффект на выручку в силу природы бизнеса; связанного с поставками и меняющейся долей продаж по спот-ценам.', 'a096a55f725395115981f9dadbb0343fdcf2241ab6b9298934677cdcc5621e0d', 'f564ac5f06419c13ec840202fd6112458d757f336d1c845d1cec113556bd5232', 1214, 320, '{1}', 1, 1, '[]', '{"oversized": false, "source_size": 320, "source_chunk_id": "ALFA_Russian_Steels_1К21PreviewUpdate_15Apr2021#0002"}', '2026-10-22 15:55:26.210565+00', '2026-10-22 15:55:26.210565+00') ON CONFLICT DO NOTHING;
