INSERT INTO public.analytics_chunks (id, document_id, ordinal, kind, section_path, text, embedding_text, content_hash, input_hash, chars, size, pages, page_from, page_to, table_refs, metadata, created_at, updated_at) VALUES ('alfa-fi-strategy-3q26#b533f14a6988e48a', 'alfa-fi-strategy-3q26', 1, 'text', '{Предисловие}', 'Российский рынок облигаций к середине 2026 г. разделился на 5 относительно независимых сегментов:

- [ ] ОФЗ c фиксированным купоном (ОФЗ-ПД): Классические ОФЗ, на которые до 2022 г. приходилось более 90% объема рынка гособлигаций. К середине 2026 г доля ЭТОГО сегмента объеме публичного   госдолга снизилась до 60%. Рынок ОФЗ-ПД подразделяется на краткосрочные ОФЗ (сроком обращения до 3-х лет), среднесрочные (3-6 лет), более долгосрочные (6-10 лет) и долгосрочные (более 10 лет). Именно долгосрочные ОФЗ являются самым рискованным сегментом среди ОФЗ-ПД из-за высокой амплитуды колебания цены при изменении доходности. В 1П26 г длинные ОФЗ показали худший результат среди вcex классов облигаций. Общий объем ОФ-ПД в обращении составляет ~20 трлн руб. по номиналу.', 'Документ: Долговой рынок
Раздел: Предисловие

Российский рынок облигаций к середине 2026 г. разделился на 5 относительно независимых сегментов:

- [ ] ОФЗ c фиксированным купоном (ОФЗ-ПД): Классические ОФЗ, на которые до 2022 г. приходилось более 90% объема рынка гособлигаций. К середине 2026 г доля ЭТОГО сегмента объеме публичного   госдолга снизилась до 60%. Рынок ОФЗ-ПД подразделяется на краткосрочные ОФЗ (сроком обращения до 3-х лет), среднесрочные (3-6 лет), более долгосрочные (6-10 лет) и долгосрочные (более 10 лет). Именно долгосрочные ОФЗ являются самым рискованным сегментом среди ОФЗ-ПД из-за высокой амплитуды колебания цены при изменении доходности. В 1П26 г длинные ОФЗ показали худший результат среди вcex классов облигаций. Общий объем ОФ-ПД в обращении составляет ~20 трлн руб. по номиналу.', 'b533f14a6988e48a518ed0566120d29e5e59d6e72175db8c434398be4bb6cec0', 'd57809d00c934d9297ec27d639cb782dbbc395ba4129138de77b69c32458ea34', 766, 213, '{2}', 2, 2, '[]', '{"oversized": false, "source_size": 213, "source_chunk_id": "FI_Strategy_3Q26_22072026#0002"}', '2026-10-22 15:55:26.240816+00', '2026-10-22 15:55:26.240816+00') ON CONFLICT DO NOTHING;
