INSERT INTO public.analytics_chunks (id, document_id, ordinal, kind, section_path, text, embedding_text, content_hash, input_hash, chars, size, pages, page_from, page_to, table_refs, metadata, created_at, updated_at) VALUES ('alfa-fi-strategy-3q26#ae270f04a858c2ed', 'alfa-fi-strategy-3q26', 3, 'text', '{Предисловие}', '- [ ] Корпоративные облигации c переменным купоном. Основной инструмент привлечения компаниями средств на публичном долговом рынке, формируют более 50% рынка, купон привязан к уровню ключевой ставки или RUONIA и в подавляющем большинстве случаев определяется формуле КС+спред: He зависят от конъюнктуры на рынке ОФЗ-ПД: Из-за доминирования выпусков плавающей ставкой, сегмент корпоративных облигаций котвязалсях от рынка ОФЗ, теперь рост доходности ОФЗ не препятствует активному размещению корпоративных облигаций, т.к. основным параметром для этого сегмента является уровень ключевой ставки, a не доходность ОФЗ (как было до 2022 г ):

- [ ] Валютные облигации: Номинированные иностранной валюте гособлигации и облигации российских компаний, размещенные российскому праву, выплаты в большинстве случаев осуществляются рублях по курсу ЦБ РФ: Основными инвесторами являются частные (преимущественно, крупные) инвесторы. Динамика процентных ставок по валютным российским облигациям не зависит от уровня процентных ставок мире и определяется исключительно уровнем спроса CO стороны российских инвесторов.

Инвестиционное резюме:', 'Документ: Долговой рынок
