INSERT INTO public.analytics_chunks (id, document_id, ordinal, kind, section_path, text, embedding_text, content_hash, input_hash, chars, size, pages, page_from, page_to, table_refs, metadata, created_at, updated_at) VALUES ('alfa-fi-strategy-3q26#ca46423b10fc0d73', 'alfa-fi-strategy-3q26', 18, 'text', '{"Потребительский спрос заметное ускорение"}', '- Спрос  населения вернулся на траекторию активного роста:  Сохранение темпов роста   зарплат на уровне двузначных значений, также снижение ставок, поддержавшее восстановление потребкредитования, стали стимулами расширению трат что придало импульс к росту оборота розничной торговли (см. график справа) и рыночной ипотеки (график ниже): Рынок труда остается жестким, небольшое снижение темпов роста зарплат апреле (см. график ниже) пока трудно назвать устойчивым трендом. Восстановление потребительского спроса на протяжении нескольких месяцев подряд условиях повышенных инфляционных рисков; по нашему мнению, ограничивает пространство для снижения ключевой ставки на заседании ЦБ 24 июля
- Настроения потребителей и производителей разошлись: Индикатор бизнес-климата июле снизился до -3,6 п , что стало минимальным значением c середины 2022 г. Тем не менее, ЦБ считает, ЧТО условиях действия значимых ШОков предложения настоящий момент (снижение нефтепереработки) возможную умеренную динамику деловой активности ближайшие месяцы не стоит напрямую относить дезинфляционному импульсу важное значение будут иметь вторичные эффекты на динамику активности в других отраслях Масштаб вторичных эффектов в значительной степени зависит от продолжительности шока предложения

