INSERT INTO public.analytics_chunks (id, document_id, ordinal, kind, section_path, text, embedding_text, content_hash, input_hash, chars, size, pages, page_from, page_to, table_refs, metadata, created_at, updated_at) VALUES ('alfa-fi-strategy-3q26#b77775f21c7bf2f3', 'alfa-fi-strategy-3q26', 20, 'text', '{"Инфляция снижается недостаточно быстро"}', '- Инфляция в июне существенно ускорилась: В июне рост потребительских цен составил 0,87% против 0,17% в мае Основной вклад темп роста цен внесло топливо, причем этот фактор может и дальнейшем оказать заметное проинфляционное влияние через вторичные эффекты. Годовая инфляция в апреле-мае замедлилась, однако значительный вклад замедление цен внесли временные факторы . По мнению ЦБ, дезинфляционные тенденции развиваются, но не так быстро, как может казаться исходя из динамики общего индекса потребительских цен роста
- Услуги дорожают повышенными темпами Медианный рост стоимости услуг в 1п26 г стабилизировался на повышенном уровне (заметно выше уровня 2/25 г) Рост цен на нерегулируемые услуги (бытовые и медицинские) остается очень высоким, ЧТО может говорить 0 сохранении повышенных темпов устойчивого роста цен. По мнению ЦБ; при сохранении опережающего роста цен сфере услуг по сравнению на товары (в ТЧ. силу большего влияния зарплат на структуру   издержек инфляции на цели требуется рост цен товаров ниже целевого \_уровня инфляции
- Рост частного спроса не пользу снижения инфляции.', 'Документ: Долговой рынок
Раздел: Инфляция снижается недостаточно быстро

- Инфляция в июне существенно ускорилась: В июне рост потребительских цен составил 0,87% против 0,17% в мае Основной вклад темп роста цен внесло топливо, причем этот фактор может и дальнейшем оказать заметное проинфляционное влияние через вторичные эффекты. Годовая инфляция в апреле-мае замедлилась, однако значительный вклад замедление цен внесли временные факторы . По мнению ЦБ, дезинфляционные тенденции развиваются, но не так быстро, как может казаться исходя из динамики общего индекса потребительских цен роста
- Услуги дорожают повышенными темпами Медианный рост стоимости услуг в 1п26 г стабилизировался на повышенном уровне (заметно выше уровня 2/25 г) Рост цен на нерегулируемые услуги (бытовые и медицинские) остается очень высоким, ЧТО может говорить 0 сохранении повышенных темпов устойчивого роста цен. По мнению ЦБ; при сохранении опережающего роста цен сфере услуг по сравнению на товары (в ТЧ. силу большего влияния зарплат на структуру   издержек инфляции на цели требуется рост цен товаров ниже целевого \_уровня инфляции
