INSERT INTO public.analytics_chunks (id, document_id, ordinal, kind, section_path, text, embedding_text, content_hash, input_hash, chars, size, pages, page_from, page_to, table_refs, metadata, created_at, updated_at) VALUES ('alfa-fi-strategy-3q26#dc05e9f9a9325822', 'alfa-fi-strategy-3q26', 29, 'text', '{"Физлица предпочитают облигации"}', '- Объем притока   средств облигации   существенно опережает приток акции: Мы отмечаем заметное смещение интересов частных инвесторов в сторону долгового рынка: За прошедшие 12 месяцев   объем притока средств физлиц в облигации составил 1,8 трлн руб , время как приток акции за это время составил лишь 237 млрд руб. По итогам 1П26 г. приток средств физлиц облигации составил 994 млрд руб , ЧТО на 21% превышает результат 2/25 г Розничные инвесторы также существенно увеличили вложения фонды облигаций (см график ниже): Объем СЧА ПИФ облигаций за 5 месяцев 2026 г. увеличился на 51% до 1,2 трлн руб , в то время как прирост СЧА БПИФ денежного рынка составил лишь 15%
- Корпоративные облигации фаворит розничного инвестора: В структуре вложений физлиц публичный корпоративные облигации существенно опережают ОФЗ: Из 1,8 трлн руб. притоков за последние 12 месяцев на корпоративные облигации пришлось 1,14 трлн или 63% долг руб:
- Физлица   существенно уступают институциональным инвесторам по объему вложений облигации.', 'Документ: Долговой рынок
