INSERT INTO public.analytics_chunks (id, document_id, ordinal, kind, section_path, text, embedding_text, content_hash, input_hash, chars, size, pages, page_from, page_to, table_refs, metadata, created_at, updated_at) VALUES ('alfa-fi-strategy-3q26#5308950efcec8b72', 'alfa-fi-strategy-3q26', 33, 'text', '{"He нужно бояться опоздать c входом В рынок ОФЗ"}', '- Навес длинных ОФЗ не исчезнет на обозримом горизонте:   Текущая структура ОФЗ-ПД сроку погашения (Слайд 16) крайне важна оценки потенциала роста цены ОФЗ: Ha данный момент объеме рынка ОФЗ-ПД (20 трлн руб:) 30% (!) приходится на ОФЗ co сроком погашения более 10 лет которым относятся так активно обсуждаемые инвестсреде выпуски 26247, 26248, 26254 и 26238. И именно размещение ОФЗ-ПД на срок более 10 лет является приоритетом для Минфина при проведении аукционов ОФЗ.', 'Документ: Долговой рынок
Раздел: He нужно бояться опоздать c входом В рынок ОФЗ

