INSERT INTO public.analytics_chunks (id, document_id, ordinal, kind, section_path, text, embedding_text, content_hash, input_hash, chars, size, pages, page_from, page_to, table_refs, metadata, created_at, updated_at) VALUES ('alfa-fi-strategy-3q26#bc43b7ce57131fa6', 'alfa-fi-strategy-3q26', 34, 'text', '{"He нужно бояться опоздать c входом В рынок ОФЗ"}', 'В 1П26 объем размещения ОФЗ по номиналу составил 3,3 трлн руб: из которых на ОФЗ co сроком погашения более 10 лет пришлось 40% (1,4 трлн руб ): По нашему мнению, если произойдет улучшение рыночной конъюнктуры Минфин увеличит предложение длинных ОФЗ на аукционах, рост предложения при неизменной базе покупателей будет препятствовать росту цены длинных ОФЗ (если мы рассматриваем ОФЗ как товар): Навес предложения говорит том, ЧТО открытием позиций в длинных ОФЗ можно не спешить, т.к. нет риска опоздать для - Длинные ОФЗ рисковый актив: Графики справа иллюстрируют наш тезис 0 повышенном риске инвестиций длинные ОФЗ-ПД на примере динамики цены ОФЗ 26249 (6 лет) и 26254 (14 лет): протяжении 1П2бг: цена выпуска 26254 не росла относительно начала 2026 г в том числе из-за навеса предложения от Минфина: Обвал цены ОФЗ 26254 июне является подтверждением того, ЧТО когда происходит бегство от риска, именно длинные ОФЗ показывают наихудшую ценовую динамику, т.к. при высокой дюрации рост доходности длинных ОФЗ транслируется в более существенное снижение цены по сравнению c ОФЗ c более коротким сроком погашения - Геополитика основной драйвер для длинных ОФЗ: Для возобновления роста котировок длинных ОФЗ-ПД необходимо не улучшение рыночной конъюнктуры (в первую очередь снижение геополитических рисков), но и снижение объема предложения от Минфина (что возможно только при условии снижения дефицита бюджета), a также ликвидность, то есть приток новых денег на рынок', 'Документ: Долговой рынок
Раздел: He нужно бояться опоздать c входом В рынок ОФЗ

