INSERT INTO public.analytics_chunks (id, document_id, ordinal, kind, section_path, text, embedding_text, content_hash, input_hash, chars, size, pages, page_from, page_to, table_refs, metadata, created_at, updated_at) VALUES ('alfa-fi-strategy-3q26#b5164a16b2a9aa28', 'alfa-fi-strategy-3q26', 35, 'text', '{"He нужно бояться опоздать c входом В рынок ОФЗ"}', '(что возможно только при условии снижения дефицита бюджета), a также ликвидность, то есть приток новых денег на рынок ОФЗ

Вывод: Мы считаем ЧТО длинные ОФЗ мопт показать динамику хуже рынка даже при улучшении геополитического фона: В время как среднесрочные ОФЗ покажут опережающую динамику котировок из-за дефицита таких бумаг ограниченного нового предложения Минфина оптимальной дюрации, обеспечивающей привлекательный рост цены при снижении доходности. При снижении ключевой ставки до уровня 12% через 12 месяцев доходность ОФЗ 26249, по нашим оценкам, может снизиться так же до 12% текущих ~16%, что предполагает рост цены до 97,2% c текущих 83,4%, что обеспечит доход (рост цены+купон) в размере 30% на горизонте 12 месяцев', 'Документ: Долговой рынок
Раздел: He нужно бояться опоздать c входом В рынок ОФЗ

