INSERT INTO public.analytics_chunks (id, document_id, ordinal, kind, section_path, text, embedding_text, content_hash, input_hash, chars, size, pages, page_from, page_to, table_refs, metadata, created_at, updated_at) VALUES ('alfa-fi-strategy-3q26#19a7b5f358b43fb2', 'alfa-fi-strategy-3q26', 36, 'text', '{"Рынок растет за счет выпусков c плавающим купоном"}', '- Объем размещений 3,2 трлн руб: в 1П26 г По итогам 1П26 г: объем размещений корпоративных облигаций, по нашим расчетам, составил 3,2 трлн руб. При расчете показателя мы принимали расчет только рыночные корпоративные выпуски и не учитывали секьюритизации , ипотечные облигации, структурные продукты и ЦФА: 1П26 г большая часть объема размещений корпоративных бумаг (62%) пришлась на 2к26 г, когда конъюнктура рынка заметно ухудшилась: Это связано с тем, что больше половины размещений составляют выпуски c плавающим купоном, не зависящие от рынка ОФЗ
- Плавающий купон драйвер рынка: В структуре размещений в 1П26 г преобладали выпуски купоном, на них пришлось более 61% от общего объема размещения: В структуре находящихся обращении рыночных выпусков корпоративных облигаций на флоутеры приходится 52%
- В структуре инвесторов на первичном рынке 1П2Б Г традиционно доминировали банки (43%), существенная доля y ДУ (17%), доля физлиц составила 8%. Здесь мы приводим данные ЦБ РФ; которые учитывают более широкий круг корпоративных бумаг по сравнению c нашими расчетами

