INSERT INTO public.analytics_chunks (id, document_id, ordinal, kind, section_path, text, embedding_text, content_hash, input_hash, chars, size, pages, page_from, page_to, table_refs, metadata, created_at, updated_at) VALUES ('alfa-fi-strategy-3q26#112ce878aa71f4ce', 'alfa-fi-strategy-3q26', 37, 'text', '{"Корпоративные облигации- растущий рынок"}', '- Темп роста рынка облигаций опережает рост рынка банковского кредитования: К середине 2026 объем рынка корпоративных облигаций достиг 36,3 трлн руб  a в структуре общего объема кредитов юрлицам (кредиты облигации) доля облигаций выросла до 27% 25% на начало 2025 г. Эти данные учитывают все виды негосударственного публичного долга
- 70% рынка эмитенты инвесткатегории: Эмитенты С высшим кредитным рейтингом составляют основу рынка корпоративных облигаций. эмитентов низким рейтингом приходится лишь 4%. Именно в этом сегменте сконцентирована проблемная задолженность
- Доходность облигаций фиксированным купоном следует за ОФЗ: Рост давления на рынок ОФЗ BO 2к26 оказал негативное влияние на котировки корпоративных облигаций С фиксированным купоном (см. график ниже) Тем не менее, важно отметить, что ликвидность торгов корпоративными облигациями является крайне низкой (в т:ч. из-за существенной доли банков структуре инвесторов и их стратегии кдержать до погашениях ), и коррекция рынка не позволяет собрать c рынка существенный объем бумаг', 'Документ: Долговой рынок
Раздел: Корпоративные облигации- растущий рынок

