INSERT INTO public.analytics_chunks (id, document_id, ordinal, kind, section_path, text, embedding_text, content_hash, input_hash, chars, size, pages, page_from, page_to, table_refs, metadata, created_at, updated_at) VALUES ('alfa-fi-strategy-3q26#ba5d2d06174bcb1c', 'alfa-fi-strategy-3q26', 38, 'text', '{"Корпоративные облигации фокус строго на качество и баланс"}', '- Эмитенты поисках небанковского спроса из-за ограничений по лимитам. Важной   особенностью российского рынка корпоративных облигаций является высокая концентрация долга на нескольких крупнейших эмитентах: Ha mоп-10 эмumeнmoe прuxodumcя ~60% рынка, при этом российским институциональным инвесторам необходимо диверсифицировать портфель облигаций для управления риском на одного заемщика: Доминирование нескольких крупнейших заемщиков на российском рынке приводит перманентной кбитве за Отметим, что банки наращивают портфель корпоративных облигаций существенно медленнее, чем портфель ОФЗ. По данным ЦБ; доля банков в общем объеме рынка корпоративных облигаций на начало 2026 г. составляла 29%, в то время как на прочий байсайд (УК, НПФ , ПИФы, инвестфонды, страховые компании) пришлось доля населения составляла 9% 42%,
- При развороте ДКП кредитные риски неизбежно вырастут.', 'Документ: Долговой рынок
