INSERT INTO public.analytics_chunks (id, document_id, ordinal, kind, section_path, text, embedding_text, content_hash, input_hash, chars, size, pages, page_from, page_to, table_refs, metadata, created_at, updated_at) VALUES ('alfa-fi-strategy-3q26#323fd7f6f196d721', 'alfa-fi-strategy-3q26', 41, 'text', '{"Корпоративные флоутеры выбор в период неопределенности"}', '- Цены корпоративных флоутеров стабильны: Введенные ЦБ в конце 2024 г. послабления в части регуляторных требований к банкам способствовали стабилизации цен на корпоративные облигации c плавающим купоном. С начала 2025 ценовой индекс RUFLBICP стабильно держится диапазоне 94-96. Мы считаем низкой вероятность повторения сценария 2024 года, его основе лежало удорожание банковского фондирования условиях ужесточения регулирования CO стороны ЦБ РФ: Ценовая стабильность повышает привлекательность корпоративных флоутеров эмитентов кредитного качества которые можно рассматривать как защитный инструмент в условиях неопределенности
- Флоутеры альтернатива денежному  рынку: C учетом сохраняющейся геополитической напряженности , моменте мы рассматриваем качественные корпоративные флоутеры как подходящий актив для инвестирования средств ожидании более благоприятного момента входа рынок инструментов С фиксированной доходностью В условиях сохранения ключевой ставки на повышенном уровне мы отдаем предпочтение эмитентам высокого кредитного качества
- Короткие   флоутеры ликвидный инструмент: Ниже мы приводим перечень корпоративных   флоутеров эмитентов высокого кредитного качества co сроком погашения не более 18 месяцев регулярной выплатой купона. В условиях снижения ставок по депозитам, сохраняющихся рисков геополитической неопределенности , также переоценки кредитного качества эмитентов, мы считаем выпуски привлекательными для диверсификации портфеля облигаций

Источник: МосБиржа

Источник: МосБиржа, CBonds', 'Документ: Долговой рынок
