INSERT INTO public.analytics_chunks (id, document_id, ordinal, kind, section_path, text, embedding_text, content_hash, input_hash, chars, size, pages, page_from, page_to, table_refs, metadata, created_at, updated_at) VALUES ('alfa-gold-aug-2026#24fd39eb777550a3', 'alfa-gold-aug-2026', 2, 'text', '{"Причины смены роста коррекцией"}', '28 августа Кевин Уорш; глава ФРС, подчеркнул устойчивость экономики и приоритет борьбы инфляцией Переоценка перспектив ставки повысила альтернативную стоимость владения золотом; рост доходностей американских облигаций и отскок доллара США затормозили ралли; Более того, на прошлой неделе цена золота резко снизилась после выхода сильных данных по рынку труда США, которые повысили ожидания возможного повышения ставки Федеральной резервной системой августе число рабочих мест вне сельского хозяйства США выросло на 162 тысячи после пересмотра показателей за предыдущие два месяца в сторону повышения Это оказалось выше всех прогнозов аналитиков, Между тем; безработица сохранилась на уровне 4,1%. Сильная статистика заставила трейдеров активнее закладывать в цены повышение ставки ФРС в сентябре; Вероятность такого решения оценивается

примерно в 60%, тогда как ранее участники рынка практически не делали на него ставку После публикации данных укрепился доллар США до 99 пунктов; a доходность двухлетних гособлигаций США выросла до 4,3%, Для золота это негативный фактор; Теперь внимание рынка переключается на данные по потребительской инфляции в США; которые выйдут на этой неделе Именно они могут стать ключевым фактором для решения ФРС по ставке 16-ого сентября', 'Документ: ОБЗОР РЫНКА ЗОЛОТА АВГУСТ 2026
Раздел: Причины смены роста коррекцией

28 августа Кевин Уорш; глава ФРС, подчеркнул устойчивость экономики и приоритет борьбы инфляцией Переоценка перспектив ставки повысила альтернативную стоимость владения золотом; рост доходностей американских облигаций и отскок доллара США затормозили ралли; Более того, на прошлой неделе цена золота резко снизилась после выхода сильных данных по рынку труда США, которые повысили ожидания возможного повышения ставки Федеральной резервной системой августе число рабочих мест вне сельского хозяйства США выросло на 162 тысячи после пересмотра показателей за предыдущие два месяца в сторону повышения Это оказалось выше всех прогнозов аналитиков, Между тем; безработица сохранилась на уровне 4,1%. Сильная статистика заставила трейдеров активнее закладывать в цены повышение ставки ФРС в сентябре; Вероятность такого решения оценивается

примерно в 60%, тогда как ранее участники рынка практически не делали на него ставку После публикации данных укрепился доллар США до 99 пунктов; a доходность двухлетних гособлигаций США выросла до 4,3%, Для золота это негативный фактор; Теперь внимание рынка переключается на данные по потребительской инфляции в США; которые выйдут на этой неделе Именно они могут стать ключевым фактором для решения ФРС по ставке 16-ого сентября', '24fd39eb777550a39e49469faaf0359ceca4751882372d25574925bc614fbfaf', '80a3e7a98743f0d14db19d072c4d73fd49c310bbb6bab56bf9b8dd629b4e94b6', 1267, 276, '{2}', 2, 2, '[]', '{"oversized": false, "source_size": 276, "source_chunk_id": "Gold_digest_August26#0003"}', '2026-10-22 15:55:26.296285+00', '2026-10-22 15:55:26.296285+00') ON CONFLICT DO NOTHING;
INSERT INTO public.analytics_chunks (id, document_id, ordinal, kind, section_path, text, embedding_text, content_hash, input_hash, chars, size, pages, page_from, page_to, table_refs, metadata, created_at, updated_at) VALUES ('alfa-gold-aug-2026#eca528c8cd5540cb', 'alfa-gold-aug-2026', 3, 'text', '{"Китай дело тонкое"}', 'Пекин сейчас активно использует косвенную стратегию "золотого обеспечения юаня для ускорения интернационализации своей валюты , Вместо того, чтобы привязывать курс юаня, что лишило бы Народный Китая независимости в денежно кредитной политике инфраструктура, построенная в таких центрах как Шанхай и Гонконг; действует как механизм укрепления доверия в двусторонней торговле Это позволяет иностранным компаниям осуществлять операции в юанях С четкой гарантией того, что они смогут беспрепятственно конвертировать эти доходы в физическое золото банк

Реальная цель расширения золотых запасов Китая И создания локализованных оффшорных клиринговых экосистем заключается создании параллельного финансового цикла: сырье-юань-золото  Эта структура позволяет ключевым поставщикам сырья таким как; K примеру, Россия, Иран; a также, возможно; странам Персидского залива; продавать нефть или сырье Китаю напрямую за юани; Более того, торговые партнеры которые не решаются хранить фиатные юани из-за строгого контроля за движением капитала в Китае, могут мгновенно купить драгметалл через Шанхайскую биржу золота (SGE) или новую центральную клиринговую систему по драгоценным металлам Гонконга: Благодаря интеграции SGE на материковой части Китая оффшорной инфраструктурой в Гонконге расчеты по транзакциям осуществляются исключительно в юанях, a клиринг осуществляется использованием незападной инфраструктуры. Это делает систему неуязвимой для замораживания активов на Западе или запрета SWIFT', 'Документ: ОБЗОР РЫНКА ЗОЛОТА АВГУСТ 2026
Раздел: Китай дело тонкое

