INSERT INTO public.analytics_chunks (id, document_id, ordinal, kind, section_path, text, embedding_text, content_hash, input_hash, chars, size, pages, page_from, page_to, table_refs, metadata, created_at, updated_at) VALUES ('alfa-bond-brief-2026-09-14#4c5d7a97fe6c7795', 'alfa-bond-brief-2026-09-14', 0, 'text', '{"Доходность ОФЗ выросла после паузы в цикле снижения ставки"}', 'В пятницу 11 сентября ЦБ ожидаемо сохранил ключевую ставку на уровне 14,0%, однако долговые инвесторы остались разочарованы тем, что регулятор не рассматривал опцию снижения ставки. После заседания на дальнем участке кривой ОФЗ доходность выросла, на пике подойдя уровню 16,3%. 14-летний бенчмарк ОФЗ 26254 (погашение 13.10.2040 г.) завершил неделю доходностью 16,2%. В целом по итогам недели на среднем дальнем   участках кривой ОФЗ доходность выросла на 10-17 б.п.

Регулятор обеспокоен ростом устойчивой инфляции, при этом глава ЦБ Эльвира Набиуллина отметила, что в базовом сценарии ожидается снижение устойчивой инфляции по мере как эффекты От временного сокращения производственных мощностей будут   сходить на нет при условии, ЧТО рост совокупного спроса будет оставаться сдержанным. Для снижения ключевой ставки нужна уверенность в том, что это происходит:

Исmочнuкu: ЦБ, Muнфuн, МосБuржа, Альфа-Банк

Глава ЦБ сообщила, ЧТО ЦБ потребуется больше данных для оценки влияния на устойчивую инфляцию временных эффектов , a также отметила, что проинфляционные риски выросли, a экономика может вернуться дисбалансу спроса и предложения: Примечательно, что долговой рынок проигнорировал мягкий комментарий Председателя ЦБ 0 том, что если правительство предложит более быстрый выход на нулевой первичный дефицит бюджета, чем сейчас заложено в прогнозе, это будет способствовать смягчению ДКП.', 'Документ: Бонд Бриф: Итоги недели
Раздел: Доходность ОФЗ выросла после паузы в цикле снижения ставки

В пятницу 11 сентября ЦБ ожидаемо сохранил ключевую ставку на уровне 14,0%, однако долговые инвесторы остались разочарованы тем, что регулятор не рассматривал опцию снижения ставки. После заседания на дальнем участке кривой ОФЗ доходность выросла, на пике подойдя уровню 16,3%. 14-летний бенчмарк ОФЗ 26254 (погашение 13.10.2040 г.) завершил неделю доходностью 16,2%. В целом по итогам недели на среднем дальнем   участках кривой ОФЗ доходность выросла на 10-17 б.п.

Регулятор обеспокоен ростом устойчивой инфляции, при этом глава ЦБ Эльвира Набиуллина отметила, что в базовом сценарии ожидается снижение устойчивой инфляции по мере как эффекты От временного сокращения производственных мощностей будут   сходить на нет при условии, ЧТО рост совокупного спроса будет оставаться сдержанным. Для снижения ключевой ставки нужна уверенность в том, что это происходит:

Исmочнuкu: ЦБ, Muнфuн, МосБuржа, Альфа-Банк

Глава ЦБ сообщила, ЧТО ЦБ потребуется больше данных для оценки влияния на устойчивую инфляцию временных эффектов , a также отметила, что проинфляционные риски выросли, a экономика может вернуться дисбалансу спроса и предложения: Примечательно, что долговой рынок проигнорировал мягкий комментарий Председателя ЦБ 0 том, что если правительство предложит более быстрый выход на нулевой первичный дефицит бюджета, чем сейчас заложено в прогнозе, это будет способствовать смягчению ДКП.', '4c5d7a97fe6c7795612f1b98d280c90d34abb97ebc2cb54a920d74e03c9d274b', '15e98fd46a808a90a04d362fce4a607c8fe15eeb7223bfe41fb71bdad4889363', 1393, 370, '{1}', 1, 1, '[]', '{"oversized": false, "source_size": 370, "source_chunk_id": "Бонд_Бриф_14092026#0001"}', '2026-10-22 15:55:26.327126+00', '2026-10-22 15:55:26.327126+00') ON CONFLICT DO NOTHING;
