INSERT INTO public.analytics_chunks (id, document_id, ordinal, kind, section_path, text, embedding_text, content_hash, input_hash, chars, size, pages, page_from, page_to, table_refs, metadata, created_at, updated_at) VALUES ('alfa-bond-brief-2026-09-14#a5e34c1ad7dd8ed0', 'alfa-bond-brief-2026-09-14', 2, 'text', '{"Аукционы ОФЗ: Решение Минфина вернуться к размещению ОФЗ-ПД условиях сложной конъюнктуры   выглядит неожиданно"}', 'В среду 9 сентября Минфин провел аукцион размещению ОФЗ-ПД: Ранее июле ведомство объявило 0 паузе аукционах, ссылаясь на неблагоприятную конъюнктуру: По нашему мнению, заметного улучшения конъюнктуры С тех пор не произошло. Аукцион закономерно оказал умеренное давление на вторичный рынок ОФЗ: К размещению был 26218 составил 51,5 млрд руб. по номиналу, выручка от размещения 42,15 млрд руб , доходность по средневзвешенной первой половине среды выпуск подешевел и размещение прошло практически на уровне вторичного рынка. Объем размещения выпуска 26230 составил 39,16 млрд по номиналу (35,2 млрд руб. на основном аукционе и 3,95 млрд руб. на ДРПА), общая выручка составила 24,0 млрд руб: доходность по средневзвешенной цене 15,97%. Мы полагаем, ЧТО если текущей конъюнктура Минфин вернется активному размещению ОФЗ-ПД, это может оказать заметное давление на рынок ОФЗ: Кроме того, это может усилить опасения участников рынка относительно того, чего ожидать в октябре от объявления новых параметров бюджета: руб.', 'Документ: Бонд Бриф: Итоги недели
Раздел: Аукционы ОФЗ: Решение Минфина вернуться к размещению ОФЗ-ПД условиях сложной конъюнктуры   выглядит неожиданно

В среду 9 сентября Минфин провел аукцион размещению ОФЗ-ПД: Ранее июле ведомство объявило 0 паузе аукционах, ссылаясь на неблагоприятную конъюнктуру: По нашему мнению, заметного улучшения конъюнктуры С тех пор не произошло. Аукцион закономерно оказал умеренное давление на вторичный рынок ОФЗ: К размещению был 26218 составил 51,5 млрд руб. по номиналу, выручка от размещения 42,15 млрд руб , доходность по средневзвешенной первой половине среды выпуск подешевел и размещение прошло практически на уровне вторичного рынка. Объем размещения выпуска 26230 составил 39,16 млрд по номиналу (35,2 млрд руб. на основном аукционе и 3,95 млрд руб. на ДРПА), общая выручка составила 24,0 млрд руб: доходность по средневзвешенной цене 15,97%. Мы полагаем, ЧТО если текущей конъюнктура Минфин вернется активному размещению ОФЗ-ПД, это может оказать заметное давление на рынок ОФЗ: Кроме того, это может усилить опасения участников рынка относительно того, чего ожидать в октябре от объявления новых параметров бюджета: руб.', 'a5e34c1ad7dd8ed04401326eef1e5d93f491cb2aad8c6e8a0ba6de6427a466a3', '53040bf6707deac08b9318fd34a65841f2f1439f6a5714295ac39828aa28e7cc', 1012, 270, '{1}', 1, 1, '[]', '{"oversized": false, "source_size": 270, "source_chunk_id": "Бонд_Бриф_14092026#0003"}', '2026-10-22 15:55:26.327126+00', '2026-10-22 15:55:26.327126+00') ON CONFLICT DO NOTHING;
INSERT INTO public.analytics_chunks (id, document_id, ordinal, kind, section_path, text, embedding_text, content_hash, input_hash, chars, size, pages, page_from, page_to, table_refs, metadata, created_at, updated_at) VALUES ('alfa-bond-brief-2026-09-14#47820cdc8a27d4d4', 'alfa-bond-brief-2026-09-14', 3, 'text', '{"Корпоративные новости"}', 'Полюс (Эксперт РА: ruAAA Стабильный НКР: AAA.ru Стабильный)

Новость:

Рейтинговое агентство Эксперт PA 4 сентября подтвердило рейтинг компании ПАО Полюс (далее Компания) на уровне ruAAA прогноз   Стабильный. Агентство выделяет высокие показатели маржинальности , низкий уровень долга, сильную оценку ликвидности и низкий уровень корпоративных рисков

Компания:

ПАО Полюс одна из ведущих золотодобывающих компаний мира c низкой себестоимостью добычи драгоценного металла  Объем добычи золота за 2025 год составил 2529 тыс: тройских Ha данный момент Компания продолжает разработку месторождения Сухой Лог что может позволить удвоить объем добычиунций.

Облигационный долг составляет 412 млрд: руб. (около половины совокупного   долга), которого 39% номинировано в рублях, 24% в долларах США, 37% в юанях: долга

Ранее 17-го иЮля Компания провела размещение рублевых облигаций на 125 млрд: руб , что является объемом рамках одного размещения для корпоративного выпуска

Наше мнение:

В рамках публикации полугодовой отчетности Компания представила результаты по МСФО в крайне ограниченном виде;  который не позволяет полной мере   идентифицировать долговые финансовые метрики и оценить изменение Свободного Денежного Потока Дополнительно мы отмечаем, публикация результатов в ограниченном формате была представлена после рекордного размещения облигаций Компании.', 'Документ: Бонд Бриф: Итоги недели
